// mm:ss for the day clocks; the server sends absolute timestamps so a refresh keeps time.
function remainText(ms:number){if(ms<=0)return '00:00';const s=Math.ceil(ms/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function DayBar({game,now,act,busy,openPace}:{game:Game;now:number;act:(op:string,payload?:any)=>Promise<Game|null>;busy:boolean;openPace:()=>void}){
 const day=game.day;if(game.phase!=='day'||!day)return null;
 const cfg=game.settings||{speechSeconds:120,discussionMinutes:10,whisperMinutes:8};
 const seatOf=(id:string|null)=>game.players.find(p=>p.id===id)?.seat;
 const speaker=day.speaker?`${day.speaker}${seatOf(day.speakerId)?`（${seatOf(day.speakerId)} 号）`:''}`:'—';
 const speechLeft=day.speechEndsAt?day.speechEndsAt-now:0;
 const discussLeft=day.discussionEndsAt?day.discussionEndsAt-now:0;
 const whisperLeft=day.whisperEndsAt?day.whisperEndsAt-now:0;
 const mine=game.me.id===day.speakerId;
 // The day runs whispers → speeches → free discussion; there is no settlement stage any
 // more. Only rooms dealt by an older build can still sit on the legacy 'vote' stage.
 const legacyVote=day.stage==='vote';
 const steps:[string,string][]=[['whisper','私聊'],['speech','轮流发言'],['discussion','自由讨论']];
 if(legacyVote)steps.push(['vote','结算']);
 const currentIndex=Math.max(0,steps.findIndex(([key])=>key===day.stage));
 return <div className="day-bar">
  <div className="day-stages">
   {steps.map(([key,label],i)=><span key={key} className={`stage-chip${day.stage===key?' current':''}${i<currentIndex?' done':''}`}><i>{i+1}</i> {label}</span>)}
  </div>
  {day.stage==='whisper'&&<div className="day-clock"><LockKeyhole size={14}/><b>私聊环节</b><strong>{remainText(whisperLeft)}</strong><span className="day-hint">设定 {cfg.whisperMinutes} 分钟 · 只和指定玩家可见</span>{game.me.host&&<><button disabled={busy} onClick={()=>void act('end_whisper')}>结束私聊，开始发言</button><button className="ghost" disabled={busy} onClick={openPace}>节奏设置</button></>}</div>}
  {day.stage==='speech'&&<div className="day-clock"><Clock3 size={15}/><b>轮到 {speaker}</b><strong>{remainText(speechLeft)}</strong><span className="day-hint">每人 {cfg.speechSeconds} 秒 · 超时自动换人并广播</span>{(mine||game.me.host)&&<button disabled={busy} onClick={()=>void act('end_speech')}>结束发言</button>}{game.me.host&&!mine&&<button className="ghost" disabled={busy} onClick={()=>void act('end_speech')}>跳过</button>}{game.me.host&&<button className="ghost" disabled={busy} onClick={openPace}>节奏设置</button>}</div>}
  {day.stage==='discussion'&&!day.discussionOver&&<div className="day-clock"><Clock3 size={15}/><b>自由讨论</b><strong>{remainText(discussLeft)}</strong><span className="day-hint">设定 {cfg.discussionMinutes} 分钟 · 可以发起提名</span>{game.me.host&&<><button disabled={busy} onClick={()=>void act('end_discussion')}>结束讨论</button><button className="ghost" disabled={busy} onClick={openPace}>节奏设置</button></>}</div>}
  {day.stage==='discussion'&&day.discussionOver&&<div className="day-clock"><Megaphone size={15}/><b>说书人宣布：自由讨论结束</b><span className="day-hint">提名继续开放；没有人被提名时，房主可直接结束白天</span>{game.me.host&&<><button disabled={busy||!!game.ballot} onClick={()=>void act('end_day')}>结束白天 <Moon size={13}/></button><button className="ghost" disabled={busy} onClick={openPace}>节奏设置</button></>}</div>}
  {legacyVote&&<div className="day-clock"><Vote size={15}/><b>讨论已结束</b><span className="day-hint">确认提名结果后，房主点「结束白天」结算</span></div>}
 </div>;
}
// A nomination plays as a short scene instead of a bare tally: the nominator states the
// case, the nominee answers, and only then does the 15-second vote open. Each beat is
// driven by the player who owns the floor; the host keeps an override so a disconnected
// player cannot freeze the table on a nomination.
function BallotPanel({game,now,act,busy}:{game:Game;now:number;act:(op:string,payload?:any)=>Promise<Game|null>;busy:boolean}){
 const b=game.ballot!;const stage=b.stage||'vote';
 const nameOf=(id:string)=>game.players.find(p=>p.id===id)?.name||'玩家';
 const nominator=nameOf(b.nominator),nominee=nameOf(b.nominee);
 const mine=game.me.id===b.nominator?'accuse':game.me.id===b.nominee?'defense':null;
 const left=b.voteEndsAt?Math.max(0,b.voteEndsAt-now):0;
 const steps:[string,string,string][]=[['accuse','提名陈述',nominator],['defense','被提名者狡辩',nominee],['vote','限时投票',`${b.seconds||15} 秒`]];
 const current=stage==='accuse'?0:stage==='defense'?1:2;
 return <>
  <p><b>{nominator}</b> 提名了 <b>{nominee}</b>。{stage==='accuse'?`先由 ${nominator} 陈述提名理由，说完按按钮。`:stage==='defense'?`现在轮到 ${nominee} 为自己辩解。`:''}</p>
  <div className="debate-steps">{steps.map(([key,label,who],i)=><span key={key} className={`debate-step${i===current?' current':''}${i<current?' done':''}`}><i>{i+1}</i><b>{label}</b><small>{who}</small></span>)}</div>
  {stage!=='vote'?<div className="debate-body">
    <p className="debate-hint">{mine===stage?(stage==='accuse'?'讲完理由再按按钮，接下来就轮到对方狡辩。':'说完再按按钮，随即开始 15 秒投票。'):`等待 ${stage==='accuse'?nominator:nominee} ${stage==='accuse'?'陈述理由':'狡辩'}…`}</p>
    <div className="action-footer"><span className="subtle">按顺序进行 · 房主可代按</span><div className="action-row">
      {mine===stage&&<button className="primary small" disabled={busy} onClick={()=>void act('advance_ballot')}>{stage==='accuse'?`陈述完毕，轮到 ${nominee}`:'狡辩完毕，开始投票'} <ArrowRight size={14}/></button>}
      {mine!==stage&&game.me.host&&<button className="secondary small" disabled={busy} onClick={()=>void act('advance_ballot')}>{stage==='accuse'?'代按：进入狡辩':'代按：开始投票'}</button>}
      {game.me.host&&<button className="ghost small" disabled={busy} onClick={()=>void act('close_vote')}>跳过并结算</button>}
    </div></div>
  </div>:<>
    <div className="vote-clock"><Clock3 size={15}/><b>限时投票</b><strong>{remainText(left)}</strong><span>倒计时结束自动结算 · 没投的人视为不赞成 · 已投 {b.submitted}/{b.eligible}</span></div>
    <div className="vote-buttons"><button className={b.myVote===true?'vote-selected':''} disabled={busy||(!game.me.alive&&!game.me.ghostVote)} onClick={()=>void act('vote',{yes:true})}><Check size={15}/> 赞成</button><button className={b.myVote===false?'vote-selected':''} disabled={busy} onClick={()=>void act('vote',{yes:false})}><X size={15}/> 不赞成</button></div>
    <p className="vote-detail">赞成：{b.yes?.length?b.yes.join('、'):'还没有人举手'}{b.no?.length?` · 不赞成：${b.no.join('、')}`:''}{game.me.roleKey==='butler'&&game.me.alive?` · 你的主人是 ${game.me.butlerMasterId?nameOf(game.me.butlerMasterId):'尚未选择'}，只有主人投赞成时你的票才计入`:''}</p>
    <div className="action-footer"><span className="subtle">截止前可以改票</span>{game.me.host&&<button className="secondary small" disabled={busy} onClick={()=>void act('close_vote')}>提前结束投票</button>}</div>
  </>}
 </>;
}
function Initial({name,index=0}:{name:string;index?:number}){return <div className={`avatar avatar-${index%5}`} aria-label={name}>{name.slice(0,1)}</div>}
function ClockArt(){return <div className="art-wrap" aria-hidden="true"><div className="art-stars star-one">✦</div><div className="art-stars star-two">✧</div><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="clock-face"><div className="clock-rim"><div className="clock-mark top">XII</div><div className="clock-mark right">III</div><div className="clock-mark bottom">VI</div><div className="clock-mark left">IX</div><div className="clock-inner"><div className="clock-moon">☾</div><div className="clock-title">THE NIGHT<br/>BEGINS</div><div className="clock-line"/><div className="clock-tiny">A STORY AWAITS</div></div></div></div><div className="art-caption">EVERY STORY HAS TWO SIDES <span>✦</span> EVERY STORY HAS TWO SIDES</div></div>}

