 const drafts=useRef<Record<string,string>>({}),recipientRef=useRef('');
 const [ravenTarget,setRavenTarget]=useState('');
 useEffect(()=>{if(!game?.ravenPending)setRavenTarget('')},[game?.ravenPending]);
 // Incoming whispers must find the player instead of waiting to be discovered: remember
