 const [seenIds,setSeenIds]=useState<Record<string,string[]>>({});
 const [ai,setAi]=useState<Ai>({key:'',region:'aliyun',model:'qwen-plus',provider:'dashscope',voiceKey:'',speaker:'zh_female_lingling_uranus_bigtts'});
