 const readRoom=useCallback(async(c:string,t:string)=>{try{const r=await fetch(apiUrl(`/api/room?code=${encodeURIComponent(c)}`),{headers:{'X-Room-Token':t},cache:'no-store'});const j:any=await r.json();if(r.ok)return setGame(j);if(r.status===400&&/身份凭证|没有找到房间/.test(String(j?.error||'')))droppedFromRoom(/没有找到房间/.test(String(j.error))?'房间已不存在':'你已不在这个房间里，可能已被房主请出');}catch{}},[]);
 useEffect(()=>{const initial=new URL(window.location.href);const share=initial.searchParams.get('sharecode');if(share)setHomeHref(`/?sharecode=${encodeURIComponent(share)}`);const query=initial.searchParams.get('room');if(query){setCode(query.toUpperCase().slice(0,6));setMode('join');}try{const s=JSON.parse(sessionStorage.getItem(roomKey)||'null');if(s?.code&&s?.token){setToken(s.token);readRoom(s.code,s.token);}}catch{}},[readRoom]);
